import crypto from 'crypto';
import { cache } from 'react';
import { cookies } from 'next/headers';
import { getPool } from './db';
import { hashPassword, verifyPassword } from './adminAuth';
import { findMembershipById } from './register';

/**
 * Sign-in for trust members on the public website (the "members' corner").
 *
 * A member signs in with any ID the trust has given them (membership ID, an
 * old register number, or their trust ID) or their e-mail address, plus a
 * password. The first password is generated by the trust and e-mailed; it
 * must be changed at first sign-in.
 *
 * Sessions are rows in member_sessions (only a hash of the cookie is stored),
 * so the trust can end them at any time. This is separate from the trustees'
 * logins in every way: different table, different cookie, different host.
 */

export const MEMBER_COOKIE = 'ckp_member_session';
const SESSION_DAYS = 7;
const MAX_ATTEMPTS = 5;
const LOCK_MINUTES = 15;

const hashToken = (token) => crypto.createHash('sha256').update(String(token)).digest('hex');

/**
 * A one-time password that is easy to read out and type on a phone: "ckp" and
 * five digits, for example ckp48271. No capitals, no symbols. It works once
 * (the member must choose their own at first sign-in) and five wrong tries
 * lock the login for 15 minutes, so it does not need to be long.
 */
export function generateMemberPassword() {
  return `ckp${crypto.randomInt(10000, 100000)}`;
}

export function memberPasswordProblem(password) {
  const p = String(password || '');
  if (p.length < 6) return 'Please use at least 6 characters.';
  if (p.length > 200) return 'That password is too long.';
  if (/^(.)\1+$/.test(p) || ['123456', '1234567', '12345678', 'password', 'abcdef'].includes(p.toLowerCase())) return 'Please choose something a little harder to guess.';
  return null;
}

export function memberCookieOptions(expiresAt) {
  return { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'lax', path: '/', expires: expiresAt };
}

/** Which person an identifier belongs to: any trust ID first, then an e-mail address held by exactly one person. */
async function personIdFor(identifier) {
  const raw = String(identifier || '').trim();
  if (raw.length < 3) return null;
  const pool = getPool();
  if (raw.includes('@')) {
    const { rows } = await pool.query(
      `select p.id from people p join member_accounts a on a.person_id = p.id
        where p.deleted_at is null and lower(p.email) = lower($1) limit 2`, [raw]);
    return rows.length === 1 ? rows[0].id : null;
  }
  const found = await findMembershipById(raw);
  if (found) return found.person.id;
  const { rows } = await pool.query(
    "select id from people where deleted_at is null and merged_into_id is null and upper(replace(code, ' ', '')) = upper(replace($1, ' ', '')) limit 1", [raw]);
  return rows[0]?.id || null;
}

/**
 * Checks an ID and password. Returns { ok, token, expiresAt, mustChange } or
 * { ok: false, error: 'invalid' | 'locked' | 'inactive', minutes }.
 * The same "invalid" is returned whether the ID or the password was wrong.
 */
export async function memberLogin({ identifier, password }) {
  const pool = getPool();
  const personId = await personIdFor(identifier);
  if (!personId) {
    verifyPassword(String(password || ''), 'scrypt:00:00'); // spend the same time either way
    return { ok: false, error: 'invalid' };
  }
  const { rows } = await pool.query('select * from member_accounts where person_id = $1', [personId]);
  const account = rows[0];
  if (!account) return { ok: false, error: 'invalid' };
  if (!account.is_active) return { ok: false, error: 'inactive' };
  if (account.locked_until && new Date(account.locked_until) > new Date()) {
    return { ok: false, error: 'locked', minutes: Math.max(1, Math.ceil((new Date(account.locked_until) - Date.now()) / 60000)) };
  }
  if (!verifyPassword(String(password || ''), account.password_hash)) {
    const attempts = account.failed_attempts + 1;
    const lock = attempts >= MAX_ATTEMPTS;
    await pool.query(
      `update member_accounts set failed_attempts = $2, locked_until = case when $3 then now() + ($4 || ' minutes')::interval else locked_until end where id = $1`,
      [account.id, lock ? 0 : attempts, lock, String(LOCK_MINUTES)]);
    return lock ? { ok: false, error: 'locked', minutes: LOCK_MINUTES } : { ok: false, error: 'invalid' };
  }
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + SESSION_DAYS * 86400000);
  await pool.query('insert into member_sessions (account_id, token_hash, expires_at) values ($1,$2,$3)', [account.id, hashToken(token), expiresAt]);
  await pool.query('update member_accounts set failed_attempts = 0, locked_until = null, last_login_at = now() where id = $1', [account.id]);
  await pool.query('delete from member_sessions where expires_at < now()').catch(() => {});
  return { ok: true, token, expiresAt, mustChange: account.must_change_password };
}

/** The signed-in member (account + person), or null. One query per request. */
export const getCurrentMember = cache(async () => {
  const token = cookies().get(MEMBER_COOKIE)?.value;
  if (!token || !/^[0-9a-f]{64}$/.test(token)) return null;
  const { rows } = await getPool().query(
    `select a.id as account_id, a.must_change_password, s.id as session_id,
            p.id as person_id, p.code as person_code, p.name_en, p.name_mr, p.email, p.phone, p.phone_alt,
            p.address, p.city, p.pincode, p.date_of_birth, p.blood_group
       from member_sessions s
       join member_accounts a on a.id = s.account_id
       join people p on p.id = a.person_id
      where s.token_hash = $1 and s.expires_at > now() and a.is_active and p.deleted_at is null`, [hashToken(token)]);
  return rows[0] || null;
});

export async function memberLogout() {
  const token = cookies().get(MEMBER_COOKIE)?.value;
  if (token) await getPool().query('delete from member_sessions where token_hash = $1', [hashToken(token)]);
}

/**
 * Creates the login for a person, or gives an existing one a fresh password.
 * Returns the plain password so the caller can e-mail it; it is stored only as a hash.
 * `client` may be a transaction client.
 */
export async function issueMemberCredentials(personId, client = getPool()) {
  const password = generateMemberPassword();
  const { rows } = await client.query(
    `insert into member_accounts (person_id, password_hash, must_change_password)
     values ($1, $2, true)
     on conflict (person_id) do update
       set password_hash = excluded.password_hash, must_change_password = true, is_active = true,
           failed_attempts = 0, locked_until = null, updated_at = now()
     returning id`, [personId, hashPassword(password)]);
  await client.query('delete from member_sessions where account_id = $1', [rows[0].id]);
  return { accountId: rows[0].id, password };
}

export async function setMemberPassword(accountId, password, keepSessionId = null) {
  const pool = getPool();
  await pool.query('update member_accounts set password_hash = $2, must_change_password = false, updated_at = now() where id = $1', [accountId, hashPassword(password)]);
  await pool.query('delete from member_sessions where account_id = $1 and ($2::uuid is null or id <> $2::uuid)', [accountId, keepSessionId]);
}

export { verifyPassword };
